/* Translate a key, filling {placeholders}. Falls back to English, then to the key itself. */
Oscar.t = function (key, vars) {
  var lang = Oscar.state ? Oscar.state.lang : "he";
  var dict = Oscar.i18n.strings[lang] || {};
  var val = dict[key];
  if (val === undefined) val = Oscar.i18n.strings.en[key];
  if (val === undefined) return key;
  if (typeof val === "string" && vars) {
    val = val.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] !== undefined ? vars[k] : m; });
  }
  return val;
};

/* Pick the current language from a {he, en, ar, ru} object (used for product text). */
Oscar.tx = function (obj) {
  if (!obj || typeof obj === "string") return obj || "";
  var lang = Oscar.state ? Oscar.state.lang : "he";
  return obj[lang] || obj.en || obj.he || "";
};
